<?php
/** Real footer and guarded writes on a disposable WordPress site, never production. */
if (!defined('ABSPATH') || !getenv('SUITEEDGE_FOOTER_FIXTURE') || !getenv('SUITEEDGE_FOOTER_LINKS')) { throw new RuntimeException('Explicit private footer fixtures required.'); }
wp_set_current_user(get_user_by('login','qa_admin')->ID);set_current_screen('suiteedge-migrator-mapping');
$checks=0;$check=function($ok,$label)use(&$checks){if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;};
$json=file_get_contents(getenv('SUITEEDGE_FOOTER_FIXTURE'));$export=(new SuiteEdge\Migrator\Import\DiviExportReader())->read_json($json);$links=json_decode(file_get_contents(getenv('SUITEEDGE_FOOTER_LINKS')),true)['links'];
$builder=new SuiteEdge\Migrator\Elementor\DocumentBuilder();$data=(new SuiteEdge\Migrator\Elementor\Classic\Serializer())->serialize($builder->build($export['post_content'],['presets'=>$export['presets'],'link_map'=>$links,'source_origin'=>'https://suiteedge.com']));
$counts=[];$buttons=[];$images=[];$walk=function($nodes)use(&$walk,&$counts,&$buttons,&$images){foreach($nodes as$n){if(strpos($n['settings']['_css_classes']??'','suiteedge-font-carrier')!==false){continue;}$type=$n['widgetType']??$n['elType'];$counts[$type]=($counts[$type]??0)+1;if($type==='button')$buttons[$n['settings']['text']]=$n['settings'];if($type==='image')$images[]=$n['settings'];$walk($n['elements']);}};$walk($data);
$check(!$builder->warnings,'five reported conversion warnings resolved');$check(!isset($counts['shortcode'])&&array_sum($counts)===53,'all 52 source modules plus portable carrier represented');
$check(count($images)===1&&$images[0]['link']['url']===home_url('/'),'logo uses destination frontend home');
foreach(['9990 Coconut Rd'=>'map-marker-alt','Bonita Springs, FL 34135'=>'map-marker-alt','(239) 610-1003'=>'phone-alt','info@suiteedge.com'=>'envelope']as$text=>$icon){$check($buttons[$text]['selected_icon']['value']==='fas fa-'.$icon&&$buttons[$text]['icon_align']==='left','actual contact glyph and left placement '.$text);}
$check(count(array_filter($buttons,function($b){return empty($b['selected_icon']['value']);}))===16,'all sixteen navigation buttons retain disabled icons');
$check((new SuiteEdge\Migrator\Elementor\Validator())->validate($data,true),'native controls validate with full admin metadata');
$requests=0;$offline=function($pre,$args,$url)use(&$requests){$requests++;return new WP_Error('offline_footer','No network in footer pilot');};add_filter('pre_http_request',$offline,20,3);
foreach($export['images']as$url=>$asset){$existing=(new SuiteEdge\Migrator\Assets\DuplicateDetector())->find_existing($url);$image=$existing?['id'=>$existing]:(new SuiteEdge\Migrator\Assets\EmbeddedImageImporter())->import($url,$asset,0);$check(is_array($image)&&get_post_type($image['id'])==='attachment','actual embedded footer image '.basename($url));}
$source=(new SuiteEdge\Migrator\Import\SourceRepository())->save($json,'Footer.json');$repo=new SuiteEdge\Migrator\Jobs\JobRepository();$runner=new SuiteEdge\Migrator\Jobs\BatchRunner($repo);$backup=new SuiteEdge\Migrator\Import\BackupEngine();
$page=wp_insert_post(['post_type'=>'page','post_status'=>'draft','post_title'=>'QA assigned footer','post_content'=>'Original footer page']);$initial=$backup->fingerprint($page);
$make=function($source,$page,$dry=false,$review=false)use($repo,$links){$job=new SuiteEdge\Migrator\Jobs\Job();$job->settings=['output_engine'=>'classic','dry_run'=>$dry,'assets'=>['reuse_library','import_external'],'link_map'=>$links,'source_origin'=>'https://suiteedge.com','reviewed_warnings'=>$review];$job->items=[['source_id'=>$source,'layout_index'=>0,'name'=>'Footer.json','target_page_id'=>$page,'status'=>'pending']];$job->summary['total']=1;$repo->save($job);return$job;};
$dry=$make($source,$page,true);$check($runner->process_batch($dry->id)['status']==='completed','real footer analysis completes');$check($backup->fingerprint($page)===$initial,'analysis leaves assigned page unchanged');
$apply=$make($source,$page);$check($runner->process_batch($apply->id)['status']==='completed','real footer applies to assigned page');$applied=$repo->get($apply->id);$check($applied->items[0]['target_page_id']===$page&&get_post_meta($page,'_elementor_edit_mode',true)==='builder','assigned target receives Elementor data');
$check(get_post($page)->post_content==='Original footer page'&&get_post_status($page)==='draft','original content and publication state retained');
$html=Elementor\Plugin::$instance->frontend->get_builder_content_for_display($page,true);$check(strpos($html,'e-fas-phone-alt')!==false||strpos($html,'fa-phone-alt')!==false,'actual phone glyph renders');$check(strpos($html,'e-fas-envelope')!==false||strpos($html,'fa-envelope')!==false,'actual mail glyph renders');$check(strpos($html,'@ET-DC@')===false&&strpos($html,'[et_pb_')===false,'no dynamic tokens or source shortcodes rendered');
$check($requests===0,'all imports use embedded data without remote requests');$check($runner->rollback($apply->id)['status']==='rolled_back'&&$backup->fingerprint($page)===$initial,'footer rollback restores assigned page');
$badtoken='@ET-DC@'.base64_encode(wp_json_encode(['dynamic'=>true,'content'=>'unsupported_site_binding','settings'=>[]])).'@';$badsource=(new SuiteEdge\Migrator\Import\SourceRepository())->save(wp_json_encode(['data'=>'[et_pb_image src="https://example.test/logo.png" url="'.$badtoken.'" /]']),'bad-footer.json');
$bad=$make($badsource,$page);$check($runner->process_batch($bad->id)['status']==='completed_with_errors'&&$backup->fingerprint($page)===$initial,'unknown binding still blocks assigned-page write');$drafts=wp_count_posts('page')->draft;$badnew=$make($badsource,0);$check($runner->process_batch($badnew->id)['status']==='completed_with_errors'&&wp_count_posts('page')->draft===$drafts,'unsupported binding creates no target draft');
wp_update_post(['ID'=>$page,'post_status'=>'publish']);$published=$backup->fingerprint($page);$guard=$make($source,$page);$check($runner->process_batch($guard->id)['status']==='completed_with_errors'&&$backup->fingerprint($page)===$published,'source-link warnings still protect published targets');$review=$make($source,$page,false,true);$check($runner->process_batch($review->id)['status']==='completed','reviewed source-link warnings allow published footer');$check($runner->rollback($review->id)['status']==='rolled_back'&&$backup->fingerprint($page)===$published,'published footer rollback retained');
$new=$make($source,0);$check($runner->process_batch($new->id)['status']==='completed','real footer creates new target as requested in the report');$newtarget=$repo->get($new->id)->items[0]['target_page_id'];$check($newtarget>0&&get_post_status($newtarget)==='draft'&&get_post_meta($newtarget,'_elementor_edit_mode',true)==='builder','new footer target receives Elementor data and remains a draft');$check($runner->rollback($new->id)['status']==='rolled_back'&&get_post_status($newtarget)==='draft','new footer rollback retains the draft');
remove_filter('pre_http_request',$offline,20);
$previewwarnings=[];(new SuiteEdge\Migrator\Assets\AssetProcessor())->process($data,0,['assets'=>['reuse_library','import_external'],'source_origin'=>'https://suiteedge.com'],$previewwarnings,$export['images']);
$library=Elementor\Plugin::$instance->templates_manager->get_source('local');$saved=$library->save_item(['title'=>'QA portable footer','type'=>'page','content'=>$data,'page_settings'=>[]]);if(is_wp_error($saved))throw new RuntimeException($saved->get_error_message());$inserted=$library->get_data(['template_id'=>$saved]);$check($inserted['content'][0]['id']!==$data[0]['id'],'actual template insertion regenerates element IDs');
$preview=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'QA footer browser']);update_post_meta($preview,'_wp_page_template','elementor_canvas');update_post_meta($preview,'_elementor_edit_mode','builder');Elementor\Plugin::$instance->documents->get($preview)->save(['elements'=>$inserted['content'],'settings'=>[]]);(new SuiteEdge\Migrator\Elementor\CssRegenerator())->regenerate($preview);
$fixture='[et_pb_button module_id="qa-hover-icon" button_text="Hover or focus" button_url="/" button_icon="&#xf0e0;||fa||900" button_icon_color="#ff0000" button_icon_color__hover="#00ff00" button_icon_color__hover_enabled="on|hover" button_on_hover="on" /]';$testdata=(new SuiteEdge\Migrator\Elementor\Classic\Serializer())->serialize($builder->build($fixture));$fixturepage=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'QA footer hover icon']);update_post_meta($fixturepage,'_wp_page_template','elementor_canvas');update_post_meta($fixturepage,'_elementor_edit_mode','builder');Elementor\Plugin::$instance->documents->get($fixturepage)->save(['elements'=>$testdata,'settings'=>[]]);(new SuiteEdge\Migrator\Elementor\CssRegenerator())->regenerate($fixturepage);
$evidence=['assertions'=>$checks,'plugin'=>SUITEEDGE_MIGRATOR_VERSION,'database'=>defined('DB_ENGINE')?DB_ENGINE:$GLOBALS['wpdb']->db_version(),'source_sha256'=>hash('sha256',$json),'conversion_warnings'=>[],'migration_warnings'=>$applied->items[0]['warnings'],'modules'=>$counts,'embedded_images'=>count($export['images']),'source_page_links'=>count($links),'url'=>get_permalink($preview),'hover_url'=>get_permalink($fixturepage),'template_id'=>$saved,'assigned_target'=>$page,'external_requests'=>$requests];
file_put_contents(ABSPATH.'../footer-results'.(defined('DB_ENGINE')?'-sqlite':'-mariadb').'.json',wp_json_encode($evidence,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo 'PASS: '.$checks.' WordPress footer assertions; preview '.get_permalink($preview).PHP_EOL;
